<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { BadgeCheck, Check, Clock3, FileText, HandCoins, X } from 'lucide-vue-next'
import { api } from '../api'
import { useSessionStore } from '../stores/session'
const session = useSessionStore()
const tab = ref<'offers'|'applications'>('offers')
const offers = ref<any[]>([])
const applications = ref<any[]>([])
const vacantUnits=ref<any[]>([])
const properties = ref<any[]>([])
const loading = ref(true)
const saving = ref(false)
const error = ref('')
const offerForm = ref({ propertyId: '', amount: '', message: '' })
const applicationForm = ref({ propertyId: '', monthlyIncome: '', employment: '', message: '' })
const leaseFor = ref<any>(null)
const leaseForm = ref({ startDate: '', endDate: '', monthlyRent: '', deposit: '0', unitId: '' })
const counterInputs=ref<Record<string,string>>({})
const counterMessages=ref<Record<string,string>>({})
const openCounter=ref<string|null>(null)
const role = computed(() => session.session?.user.role || '')
const canDecide = computed(() => ['ADMIN','OWNER'].includes(role.value))
async function load() { loading.value=true; try { const [o,a,p,u] = await Promise.all([api.get('/offers'),api.get('/applications'),api.get('/properties'),canDecide.value?api.get('/units'):Promise.resolve({data:[]})]); offers.value=o.data; applications.value=a.data; properties.value=p.data; vacantUnits.value=u.data.filter((x:any)=>x.status==='VACANT'); const sale=p.data.find((x:any)=>x.purpose==='SALE'); const rent=p.data.find((x:any)=>x.purpose==='RENT'); if (!offerForm.value.propertyId && sale) offerForm.value.propertyId=sale.id; if (!applicationForm.value.propertyId && rent) applicationForm.value.propertyId=rent.id } catch (e:any) { error.value=e.response?.data?.message || 'Could not load offers and applications.' } finally { loading.value=false } }
async function submitOffer() { saving.value=true; error.value=''; try { await api.post('/offers',{...offerForm.value,amount:Number(offerForm.value.amount)}); offerForm.value.amount=''; offerForm.value.message=''; await load() } catch (e:any) { error.value=e.response?.data?.message || 'Could not submit offer.' } finally { saving.value=false } }
async function submitApplication() { saving.value=true; error.value=''; try { await api.post('/applications',{...applicationForm.value,monthlyIncome:Number(applicationForm.value.monthlyIncome)||undefined}); applicationForm.value.message=''; await load() } catch(e:any) { error.value=e.response?.data?.message || 'Could not submit application.' } finally { saving.value=false } }
async function decideOffer(item:any,status:string) { try { await api.patch(`/offers/${item.id}/status`,{status}); await load() } catch(e:any) { error.value=e.response?.data?.message || 'Could not update offer.' } }
async function counterOffer(item:any) { if(!counterInputs.value[item.id])return; try { const body={status:'COUNTERED',amount:Number(counterInputs.value[item.id]),message:counterMessages.value[item.id]}; if(role.value==='BUYER') await api.post(`/offers/${item.id}/respond`,body); else await api.patch(`/offers/${item.id}/status`,body); counterInputs.value[item.id]=''; counterMessages.value[item.id]=''; openCounter.value=null; await load() } catch(e:any) { error.value=e.response?.data?.message || 'Could not submit counter-offer.' } }
async function respondToCounter(item:any,status:string){try{await api.post(`/offers/${item.id}/respond`,{status});await load()}catch(e:any){error.value=e.response?.data?.message||'Could not respond to the counter-offer.'}}
function latestCounter(item:any){return item.counters?.[item.counters.length-1]}
function canManageOffer(item:any){const last=latestCounter(item);return canDecide.value&&(item.status==='SUBMITTED'||(item.status==='COUNTERED'&&last?.proposer?.role==='BUYER'))}
async function reviewApplication(item:any,status:string) { try { await api.patch(`/applications/${item.id}/status`,{status}); await load() } catch(e:any) { error.value=e.response?.data?.message || 'Could not update application.' } }
function openLease(app:any) { leaseFor.value=app; leaseForm.value={startDate:new Date().toISOString().slice(0,10),endDate:'',monthlyRent:String(Number(app.property.price)),deposit:'0',unitId:''} }
async function createLease() { saving.value=true; error.value=''; try { await api.post(`/applications/${leaseFor.value.id}/lease`,{...leaseForm.value,startDate:new Date(leaseForm.value.startDate).toISOString(),endDate:new Date(leaseForm.value.endDate).toISOString(),monthlyRent:Number(leaseForm.value.monthlyRent),deposit:Number(leaseForm.value.deposit)||0, ...(leaseForm.value.unitId?{unitId:leaseForm.value.unitId}:{})}); leaseFor.value=null; await load() } catch(e:any) { error.value=e.response?.data?.message || 'Could not create lease.' } finally { saving.value=false } }
const money=(n:any)=>`PKR ${Number(n).toLocaleString()}`
onMounted(load)
</script>

<template><section class="workspace-content"><div class="section-toolbar"><div><h2>Offers and rental applications</h2><p>Negotiate sale offers and turn approved applications into leases.</p></div><div class="segmented-control"><button :class="{active:tab==='offers'}" @click="tab='offers'"><HandCoins :size="15"/> Offers <span>{{ offers.length }}</span></button><button :class="{active:tab==='applications'}" @click="tab='applications'"><FileText :size="15"/> Applications <span>{{ applications.length }}</span></button></div></div><div v-if="error" class="notice error-notice">{{ error }}</div><div v-if="loading" class="loading-row">Loading deals…</div><div v-else-if="tab==='offers'" class="deal-layout"><form v-if="role==='BUYER'" class="panel-card compact-form" @submit.prevent="submitOffer"><div class="eyebrow muted-eyebrow">MAKE AN OFFER</div><h3>Start a negotiation</h3><label>Sale listing<select v-model="offerForm.propertyId" required><option v-for="p in properties.filter((x:any)=>x.purpose==='SALE')" :key="p.id" :value="p.id">{{ p.title }} · {{ p.city }}</option></select></label><label>Your offer (PKR)<input v-model="offerForm.amount" type="number" min="1" required placeholder="45000000" /></label><label>Message (optional)<textarea v-model="offerForm.message" rows="3" placeholder="Payment plan or closing date…"></textarea></label><button class="button button-primary full-button" :disabled="saving">Submit offer</button></form><div class="deal-list"><article v-for="item in offers" :key="item.id" class="deal-card"><div class="deal-icon"><HandCoins :size="18"/></div><div class="deal-main"><div class="deal-top"><div><span class="eyebrow muted-eyebrow">{{ item.buyer?.name || 'Buyer offer' }}</span><h3>{{ item.property.title }}</h3></div><span class="status-pill" :class="item.status.toLowerCase()">{{ item.status }}</span></div><p>{{ item.property.city }} · Asking {{ money(item.property.price) }}</p><div class="deal-bottom"><b>{{ money(item.amount) }}</b><small>Submitted {{ new Date(item.createdAt).toLocaleDateString() }}</small></div><p v-if="item.message" class="deal-message">“{{ item.message }}”</p><div v-if="item.counters?.length" class="counter-timeline"><article v-for="counter in item.counters" :key="counter.id"><span>{{counter.proposer.name}}</span><b>{{money(counter.amount)}}</b><small>{{new Date(counter.createdAt).toLocaleString()}}</small><p v-if="counter.message">{{counter.message}}</p></article></div><form v-if="(canManageOffer(item)||(role==='BUYER'&&item.status==='COUNTERED'&&latestCounter(item)?.proposer?.role!=='BUYER')) && openCounter===item.id" class="counter-form" @submit.prevent="counterOffer(item)"><label>Counter amount (PKR)<input v-model="counterInputs[item.id]" type="number" min="1" required/></label><label>Message<input v-model="counterMessages[item.id]" placeholder="Revised closing terms…"/></label><button class="button button-primary">Send counter</button></form><div v-if="canManageOffer(item)" class="deal-actions"><button class="button button-outline" @click="openCounter=openCounter===item.id?null:item.id">{{role==='BUYER'?'Make counter-offer':'Counter offer'}}</button><button class="button button-outline reject" @click="decideOffer(item,'REJECTED')"><X :size="15"/> Reject</button><button class="button button-primary" @click="decideOffer(item,'ACCEPTED')"><Check :size="15"/> Accept</button></div><div v-if="role==='BUYER'&&item.status==='COUNTERED'&&latestCounter(item)?.proposer?.role!=='BUYER'" class="deal-actions"><button class="button button-outline" @click="openCounter=openCounter===item.id?null:item.id">Make counter-offer</button><button class="button button-outline reject" @click="respondToCounter(item,'REJECTED')"><X :size="15"/> Reject counter</button><button class="button button-primary" @click="respondToCounter(item,'ACCEPTED')"><Check :size="15"/> Accept {{money(latestCounter(item)?.amount)}}</button></div></div></article><div v-if="!offers.length" class="empty-state compact-empty"><h3>No offers yet</h3><p>Offers submitted by buyers will appear here.</p></div></div></div><div v-else class="deal-layout"><form v-if="['BUYER','TENANT'].includes(role)" class="panel-card compact-form" @submit.prevent="submitApplication"><div class="eyebrow muted-eyebrow">APPLY TO RENT</div><h3>Rental application</h3><label>Rental listing<select v-model="applicationForm.propertyId" required><option v-for="p in properties.filter((x:any)=>x.purpose==='RENT')" :key="p.id" :value="p.id">{{ p.title }} · {{ p.city }}</option></select></label><label>Monthly income (PKR)<input v-model="applicationForm.monthlyIncome" type="number" min="0" placeholder="450000" /></label><label>Employment<select v-model="applicationForm.employment"><option value="">Select employment</option><option>Employed</option><option>Self-employed</option><option>Business owner</option><option>Retired</option></select></label><label>Note to the owner<textarea v-model="applicationForm.message" rows="3" placeholder="Introduce yourself and your move-in plans…"></textarea></label><button class="button button-primary full-button" :disabled="saving">Submit application</button></form><div class="deal-list"><article v-for="item in applications" :key="item.id" class="deal-card"><div class="deal-icon green-icon"><FileText :size="18"/></div><div class="deal-main"><div class="deal-top"><div><span class="eyebrow muted-eyebrow">{{ item.applicant?.name || 'Rental applicant' }}</span><h3>{{ item.property.title }}</h3></div><span class="status-pill" :class="item.status.toLowerCase()">{{ item.status }}</span></div><p>{{ item.property.community }}, {{ item.property.city }} · Rent {{ money(item.property.price) }}/mo</p><div class="applicant-facts"><span>Income <b>{{ item.monthlyIncome ? money(item.monthlyIncome) : 'Not provided' }}</b></span><span>Employment <b>{{ item.employment || 'Not provided' }}</b></span></div><p v-if="item.message" class="deal-message">“{{ item.message }}”</p><div v-if="canDecide && ['SUBMITTED','REVIEWING'].includes(item.status)" class="deal-actions"><button class="button button-outline" @click="reviewApplication(item,'REVIEWING')"><Clock3 :size="15"/> Mark in review</button><button class="button button-outline reject" @click="reviewApplication(item,'REJECTED')"><X :size="15"/> Reject</button><button class="button button-primary" @click="openLease(item)"><BadgeCheck :size="15"/> Approve & create lease</button></div></div></article><div v-if="!applications.length" class="empty-state compact-empty"><h3>No applications yet</h3><p>Applications from prospective tenants will appear here.</p></div></div></div><div v-if="leaseFor" class="modal-backdrop" @click.self="leaseFor=null"><form class="panel-card lease-modal" @submit.prevent="createLease"><button type="button" class="modal-close" aria-label="Close" @click="leaseFor=null"><X/></button><div class="eyebrow muted-eyebrow">APPROVE APPLICATION</div><h2>Create an active lease</h2><p>{{ leaseFor.applicant.name }} · {{ leaseFor.property.title }}</p><div class="form-grid"><label>Lease starts<input v-model="leaseForm.startDate" type="date" required /></label><label>Lease ends<input v-model="leaseForm.endDate" type="date" required /></label><label>Monthly rent (PKR)<input v-model="leaseForm.monthlyRent" type="number" min="1" required /></label><label>Security deposit (PKR)<input v-model="leaseForm.deposit" type="number" min="0" /></label><label class="wide">Assign unit<select v-model="leaseForm.unitId"><option value="">No unit reference</option><option v-for="u in vacantUnits.filter((x:any)=>x.propertyId===leaseFor.propertyId)" :key="u.id" :value="u.id">{{u.unitNumber}} · {{u.bedrooms}} bed · {{money(u.monthlyRent)}}/mo</option></select></label></div><p class="modal-hint">Approval creates the lease and its monthly rent invoices for the entire lease term.</p><button class="button button-primary full-button" :disabled="saving">{{ saving ? 'Creating…' : 'Approve and create lease' }}</button></form></div></section></template>
